import type { ReactNode } from "react";
import { Pressable, Text, View, type ViewProps } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { CloseGlyph, StatusGlyph, type StatusTone } from "@/components/nyc-tron/ui/components/feedback/glyphs";
import { space } from "@/components/nyc-tron/ui/tokens";

export type BannerTone=StatusTone;

/** Props for {@linkcode Banner}. Drop-in for Nitro Forge's `StudioBannerProps`. */
export interface BannerProps extends Omit<ViewProps,"children"|"role"> {
  tone:BannerTone;
  /** One sentence naming what happened. Never the only place an error's recovery is described. */
  title:string;
  description?:string;
  /** A control that resolves the notice (Try again, Open settings). Rendered under the copy. */
  action?:ReactNode;
  /**
   * `status` (default) is a polite live region. `alert` is assertive: use it
   * only for a banner that appears because of something the person just did.
   */
  live?:"status"|"alert";
  /** Shows a 44pt close control. The app owns whether the banner stays mounted. */
  onDismiss?:()=>void;
  /** Screen-reader name of the close control. @default "Dismiss" */
  dismissLabel?:string;
  /** Replaces the drawn status mark. */
  icon?:ReactNode;
  className?:string;
  titleClassName?:string;
  descriptionClassName?:string;
  /** No default visual classes; the app supplies the full recipe. */
  unstyled?:boolean;
}

const tones:Record<BannerTone,string>={
  info:"border-info bg-surface-raised",
  success:"border-success bg-surface-raised",
  danger:"border-danger bg-surface-raised",
  neutral:"border-border bg-surface-sunken",
};

/**
 * Page- or pane-level notice: saved, couldn't save, offline, read-only.
 * Tone shows in the border and the drawn mark, and the title carries the
 * meaning in words, so color is never the only signal. Not dismissible unless
 * `onDismiss` is passed.
 */
export function Banner({
  tone,title,description,action,live="status",onDismiss,dismissLabel="Dismiss",icon,
  className,titleClassName,descriptionClassName,unstyled=false,...rest
}:BannerProps) {
  const styled=!unstyled;
  return (
    <View {...rest} role={live}
      accessibilityLiveRegion={live==="alert"?"assertive":"polite"}
      {...{className:joinClasses("w-full flex-row items-start",
        styled&&"gap-3 rounded-card border ps-4 py-3",styled&&tones[tone],
        styled&&(onDismiss?"pe-1":"pe-4"),className)}}>
      <View {...{className:"pt-0.5"}}>{icon??<StatusGlyph tone={tone}/>}</View>
      <View {...{className:joinClasses("min-w-0 flex-1",styled&&"gap-1 py-px")}}>
        <Text {...{className:joinClasses(styled&&"text-sm font-semibold leading-5 text-text",titleClassName)}}>{title}</Text>
        {description ? <Text {...{className:joinClasses(styled&&"text-sm leading-5 text-text-muted",descriptionClassName)}}>{description}</Text> : null}
        {action ? <View {...{className:joinClasses("self-start",styled&&"mt-2")}}>{action}</View> : null}
      </View>
      {onDismiss ? (
        <Pressable onPress={onDismiss} accessibilityRole="button" accessibilityLabel={dismissLabel}
          // Negative margins keep the 44pt target from growing the banner; the
          // cross lands centered on the title's first line.
          style={{marginVertical:-space[2.5]}}
          {...{className:joinClasses("min-h-11 min-w-11 items-center justify-center",
            styled&&"rounded-control hover:bg-surface-sunken active:opacity-70 focus-visible:ring-2 focus-visible:ring-focus")}}>
          <CloseGlyph/>
        </Pressable>
      ) : null}
    </View>
  );
}

import { View } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { space, radius, border } from "@/components/nyc-tron/ui/tokens";

/**
 * Status and close marks drawn with views, so they need no icon font, survive
 * forced colors (borders and backgrounds of a solid view stay visible) and
 * take the theme's tone tokens. Pass an `icon` to the owning component to use
 * the app's own icon set instead.
 */
export type StatusTone="info"|"success"|"danger"|"neutral";

// Fill and border in the same tone: forced colors drops backgrounds but
// keeps borders, so every part of a mark is drawn with a border too.
const FACE:Record<StatusTone,string>={
  info:"bg-info border-info",success:"bg-success border-success",
  danger:"bg-danger border-danger",neutral:"bg-text-muted border-text-muted",
};

/** 18pt disc with an "i", "!" or check cut out of it in the raised surface color. */
export function StatusGlyph({tone}:{tone:StatusTone}) {
  return (
    <View aria-hidden importantForAccessibility="no-hide-descendants"
      {...{className:joinClasses("h-[18px] w-[18px] items-center justify-center rounded-full border",FACE[tone])}}>
      {tone==="success" ? (
        // Two bars at right angles: the short stroke leads the long one.
        <View style={{width:9,height:6,marginTop:-space[0.5],transform:[{rotate:"-45deg"}]}}
          {...{className:"border-b-2 border-l-2 border-surface-raised"}}/>
      ) : (
        <View style={{alignItems:"center",gap:space[0.5],flexDirection:tone==="danger"?"column":"column-reverse"}}>
          <View style={{width:0,height:7,borderLeftWidth:border[2],borderRadius:radius[1]}} {...{className:"border-surface-raised"}}/>
          <View style={{width:2,height:2,borderWidth:border[1],borderRadius:radius[1]}} {...{className:"border-surface-raised"}}/>
        </View>
      )}
    </View>
  );
}

/** A 12pt cross made of two bars, colored by the caller's border token. */
export function CloseGlyph({className}:{className?:string}) {
  // Bars are top borders so forced colors keeps them.
  const bar=joinClasses("absolute h-0 w-3 border-t-2",className??"border-text-muted");
  return (
    <View aria-hidden importantForAccessibility="no-hide-descendants"
      style={{width:12,height:12,alignItems:"center",justifyContent:"center"}}>
      <View style={{transform:[{rotate:"45deg"}]}} {...{className:bar}}/>
      <View style={{transform:[{rotate:"-45deg"}]}} {...{className:bar}}/>
    </View>
  );
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

